import{_ as d,o as e,c as o,a6 as r}from"./chunks/framework.B_q3ZJNF.js";const p=JSON.parse('{"title":"协议字节与响应码速查","description":"","frontmatter":{"title":"协议字节与响应码速查"},"headers":[],"relativePath":"proxy-software-course/protocol-reference.md","filePath":"proxy-software-course/docs/protocol-reference.md"}'),a={name:"proxy-software-course/protocol-reference.md"};function c(h,t,n,i,l,s){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="协议字节与响应码速查" tabindex="-1">协议字节与响应码速查 <a class="header-anchor" href="#协议字节与响应码速查" aria-label="Permalink to &quot;协议字节与响应码速查&quot;">​</a></h1><p>本页只收录 companion（<code>companion/src/</code>）已经实现并被测试覆盖的协议字段；未实现的字段单独标注，不与已实现项混排。协议事实核对 <a href="https://www.rfc-editor.org/rfc/rfc1928.html" target="_blank" rel="noreferrer">RFC 1928</a>、<a href="https://www.rfc-editor.org/rfc/rfc9110.html#section-9.3.6" target="_blank" rel="noreferrer">RFC 9110 §9.3.6</a>、<a href="https://www.rfc-editor.org/rfc/rfc9112.html" target="_blank" rel="noreferrer">RFC 9112</a>。</p><h2 id="http-正向代理-请求目标形式" tabindex="-1">HTTP 正向代理：请求目标形式 <a class="header-anchor" href="#http-正向代理-请求目标形式" aria-label="Permalink to &quot;HTTP 正向代理：请求目标形式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>形式</th><th>使用场景</th><th>companion 行为</th><th>来源</th></tr></thead><tbody><tr><td>origin-form</td><td>客户端直连源站，请求行只带路径与查询字符串</td><td>判定为已是 origin-form，原样转发不改写（<code>rewriteAbsoluteForm</code> 对以 <code>/</code> 开头的目标返回 <code>null</code>）</td><td><a href="./02-http-forward-proxy.html">第 2 章</a></td></tr><tr><td>absolute-form</td><td>客户端把请求发给代理，请求行携带完整 URL</td><td><code>rewriteAbsoluteForm</code> 改写为 origin-form 并同步改写 <code>Host</code> 头，再转发给源站</td><td><a href="./02-http-forward-proxy.html">第 2 章</a></td></tr><tr><td>CONNECT</td><td>客户端请求为 HTTPS 目标建立隧道</td><td><code>handleConnect</code> 拨号成功后回 <code>HTTP/1.1 200 Connection Established</code>，之后不解释隧道内容，交给 <code>relay</code> 双向转发；拨号失败回 <code>502 Bad Gateway</code>；协议不是 <code>http:</code> 时回 <code>400 Bad Request</code></td><td><a href="./02-http-forward-proxy.html">第 2 章</a></td></tr></tbody></table><p><strong>未实现</strong>：HTTP keep-alive、请求流水线（pipelining）和任何消息体边界解析。<code>Content-Length</code> 与 chunked framing 都不校验；请求头之后的字节直接交给 <code>relay</code> 原样转发。一条连接只处理一个请求或一条隧道，详见 <a href="./divergence.html">差异清单</a>。</p><h2 id="socks5-握手与请求帧" tabindex="-1">SOCKS5：握手与请求帧 <a class="header-anchor" href="#socks5-握手与请求帧" aria-label="Permalink to &quot;SOCKS5：握手与请求帧&quot;">​</a></h2><p>字段与响应码定义于 <code>companion/src/socks5-wire.ts</code>，与 <a href="https://www.rfc-editor.org/rfc/rfc1928.html" target="_blank" rel="noreferrer">RFC 1928</a> 逐项对齐。</p><h3 id="方法协商-greeting" tabindex="-1">方法协商（greeting） <a class="header-anchor" href="#方法协商-greeting" aria-label="Permalink to &quot;方法协商（greeting）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>长度</th><th>含义</th><th>companion 支持</th></tr></thead><tbody><tr><td>VER</td><td>1 字节</td><td>协议版本，固定 <code>0x05</code></td><td>是</td></tr><tr><td>NMETHODS</td><td>1 字节</td><td>METHODS 字段长度</td><td>是</td></tr><tr><td>METHODS</td><td>NMETHODS 字节</td><td>客户端支持的认证方法列表</td><td>是（只识别 <code>NO_AUTH</code>）</td></tr></tbody></table><h3 id="method" tabindex="-1">METHOD <a class="header-anchor" href="#method" aria-label="Permalink to &quot;METHOD&quot;">​</a></h3><table tabindex="0"><thead><tr><th>值</th><th>名称</th><th>companion 支持</th></tr></thead><tbody><tr><td><code>0x00</code></td><td>NO_AUTH</td><td>是，唯一支持的认证方法</td></tr><tr><td><code>0xFF</code></td><td>NO_ACCEPTABLE</td><td>是；服务端返回后，本实现主动 <code>end()</code>，RFC 1928 同时要求客户端关闭连接</td></tr><tr><td>其他（用户名密码等）</td><td>—</td><td><strong>本课程未实现</strong></td></tr></tbody></table><h3 id="cmd" tabindex="-1">CMD <a class="header-anchor" href="#cmd" aria-label="Permalink to &quot;CMD&quot;">​</a></h3><table tabindex="0"><thead><tr><th>值</th><th>名称</th><th>companion 支持</th></tr></thead><tbody><tr><td><code>0x01</code></td><td>CONNECT</td><td>是，唯一实现的命令</td></tr><tr><td><code>0x02</code></td><td>BIND</td><td><strong>本课程未实现</strong>——回 <code>COMMAND_NOT_SUPPORTED</code> 并关闭连接</td></tr><tr><td><code>0x03</code></td><td>UDP_ASSOCIATE</td><td><strong>本课程未实现</strong>——回 <code>COMMAND_NOT_SUPPORTED</code> 并关闭连接</td></tr></tbody></table><h3 id="atyp-地址类型" tabindex="-1">ATYP（地址类型） <a class="header-anchor" href="#atyp-地址类型" aria-label="Permalink to &quot;ATYP（地址类型）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>值</th><th>名称</th><th>地址长度</th><th>companion 支持</th></tr></thead><tbody><tr><td><code>0x01</code></td><td>IPv4</td><td>4 字节</td><td>是</td></tr><tr><td><code>0x03</code></td><td>域名</td><td>1 字节长度前缀 + 变长</td><td>是</td></tr><tr><td><code>0x04</code></td><td>IPv6</td><td>16 字节</td><td>是</td></tr><tr><td>其他</td><td>—</td><td>—</td><td>否，回 <code>ADDRESS_TYPE_NOT_SUPPORTED</code></td></tr></tbody></table><h3 id="reply-响应码" tabindex="-1">REPLY（响应码） <a class="header-anchor" href="#reply-响应码" aria-label="Permalink to &quot;REPLY（响应码）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>值</th><th>名称</th><th>companion 会返回吗</th></tr></thead><tbody><tr><td><code>0x00</code></td><td>SUCCEEDED</td><td>是</td></tr><tr><td><code>0x01</code></td><td>GENERAL_FAILURE</td><td>定义于 <code>REPLY</code> 常量，供拨号失败时映射使用</td></tr><tr><td><code>0x02</code></td><td>CONNECTION_NOT_ALLOWED</td><td>是，规则命中 REJECT 时返回</td></tr><tr><td><code>0x03</code></td><td>NETWORK_UNREACHABLE</td><td>定义于 <code>REPLY</code> 常量</td></tr><tr><td><code>0x04</code></td><td>HOST_UNREACHABLE</td><td>定义于 <code>REPLY</code> 常量</td></tr><tr><td><code>0x05</code></td><td>CONNECTION_REFUSED</td><td>定义于 <code>REPLY</code> 常量</td></tr><tr><td><code>0x06</code></td><td>TTL_EXPIRED</td><td>定义于 <code>REPLY</code> 常量</td></tr><tr><td><code>0x07</code></td><td>COMMAND_NOT_SUPPORTED</td><td>是，收到 BIND/UDP_ASSOCIATE 时返回</td></tr><tr><td><code>0x08</code></td><td>ADDRESS_TYPE_NOT_SUPPORTED</td><td>是，ATYP 不识别时返回</td></tr></tbody></table><p><strong>未实现</strong>：UDP ASSOCIATE 数据通道、BIND 命令、除 NO_AUTH 外的任何认证方式，详见 <a href="./divergence.html">差异清单</a>。</p><h2 id="规则类型与动作" tabindex="-1">规则类型与动作 <a class="header-anchor" href="#规则类型与动作" aria-label="Permalink to &quot;规则类型与动作&quot;">​</a></h2><p>规则类型与匹配语义是本课程的实现选择，未对应任何外部标准；<code>route</code> 函数按数组顺序首条命中。</p><table tabindex="0"><thead><tr><th>RuleType</th><th>匹配依据</th><th>companion 实现</th></tr></thead><tbody><tr><td><code>DOMAIN</code></td><td>精确等于 <code>ctx.domain</code>（忽略大小写）</td><td>是</td></tr><tr><td><code>DOMAIN-SUFFIX</code></td><td><code>ctx.domain</code> 等于后缀或以 <code>.</code> + 后缀结尾（尊重标签边界）</td><td>是</td></tr><tr><td><code>IP-CIDR</code></td><td><code>ctx.ip</code> 落在 IPv4 CIDR 网段内</td><td>是，仅 IPv4</td></tr><tr><td><code>PORT</code></td><td><code>ctx.port</code> 的字符串形式等于规则值</td><td>是</td></tr><tr><td><code>MATCH</code></td><td>无条件命中，必须作为末尾兜底</td><td>是</td></tr></tbody></table><table tabindex="0"><thead><tr><th>RuleAction</th><th>含义</th><th>companion 实现</th></tr></thead><tbody><tr><td><code>DIRECT</code></td><td>直连目标</td><td>是</td></tr><tr><td><code>REJECT</code></td><td>主动拒绝，不发起任何网络操作</td><td>是</td></tr><tr><td><code>PROXY</code></td><td>转交给 <code>outbounds</code> 中指定的 SOCKS5 上游</td><td>是，<code>outbound</code> 必须引用一个 <code>SOCKS5</code> 类型出站</td></tr></tbody></table><p><strong>未实现</strong>：<code>IP-CIDR</code> 的 IPv6 网段匹配、基于地理位置或运营商的规则类型。</p>',23)])])}const T=d(a,[["render",c]]);export{p as __pageData,T as default};
